let audit=[],activeRecord='',activePair=[],queueOffset=0,pairCandidates=[];
const V=ValidationCore,ve=id=>document.getElementById(id),reviewer=()=>ve('reviewerCode').value.trim();
try{audit=JSON.parse(localStorage.getItem('orthoevidence.annotations.v1')||'[]');if(!Array.isArray(audit))throw Error();audit.forEach(V.validate)}catch(e){audit=[];ve('validationStorage').textContent='Não foi possível ler as avaliações locais. Exporte ou recupere um backup antes de continuar.';ve('validationStorage').dataset.blocked='true'}
function feedback(s){ve('validationFeedback').textContent=s}
function requireReviewer(){if(!/^[A-Za-z0-9_-]{2,40}$/.test(reviewer())){feedback('Preencha o código do avaliador (2–40 letras, números, _ ou -).');return false}return true}
function validationStats(){let r=V.latest(audit,reviewer(),'record',meta.run),p=V.latest(audit,reviewer(),'pair',meta.run);ve('validationProgress').textContent=`Nesta coleta e para este avaliador: ${r.length} referências avaliadas · ${p.length} pares avaliados. Histórico local: ${audit.length} decisões.`}
function renderValidation(){validationStats();if(!activeRecord&&data.length)nextRecord();if(!activePair.length&&data.length)nextPair()}
function recordSource(d){return `<h3>${esc(d.title)}</h3><small>PMID ${d.id} · ${d.year||'Ano indisponível'} · ${esc(d.type)}</small><p><a href="${d.url}" target="_blank" rel="noopener">Consultar PubMed ↗</a></p><details open><summary>Resumo original</summary><p style="white-space:pre-wrap">${esc(d.abstract||'Resumo indisponível; consultar texto completo.')}</p></details>`}
function openRecord(id){let d=data.find(x=>x.id===id);if(!d){feedback('PMID ausente nesta base.');return}activeRecord=id;let old=V.latest(audit,reviewer(),'record',meta.run).find(e=>e.ids[0]===id),c=d.counts[0];ve('recordSource').innerHTML=recordSource(d)+`<div class="field"><small>Extração automática original</small><p>${esc(d.objective||'Objetivo não extraído')}</p>${d.counts.map(c=>`<p>${c.n} ${esc(c.unit)} — ${esc(c.quote)}</p>`).join('')||'Número não extraído'}</div>`;ve('eligibility').value=old?.decision||'';ve('exclusionReason').value=old?.reason||'';ve('quickReason').value='';ve('correctObjective').value=old?.objective??d.objective;ve('objectiveStatus').value=old?.objective_status||'not_checked';ve('studyCount').value=old?old.count??'':c?.n??'';ve('countUnit').value=old?.unit||c?.unit||'studies';ve('countStatus').value=old?.count_status||'not_checked';ve('countEvidence').value=old?.evidence??c?.quote??'';ve('recordNotes').value=old?.notes||'';ve('recordPMID').value=id;validationStats()}
function nextRecord(){let done=new Set(V.latest(audit,reviewer(),'record',meta.run).map(e=>e.ids[0]));let d=data.find(d=>!done.has(d.id));if(d)openRecord(d.id);else feedback('Todas as referências desta coleta têm uma decisão para este avaliador.')}
function baseEvent(kind,ids){let ds=ids.map(id=>data.find(d=>d.id===id));return {event_id:crypto.randomUUID(),kind,ids,reviewer:reviewer(),run:meta.run,hashes:ds.map(d=>d.hash),saved_at:new Date().toISOString(),protocol:'orthodontic-reviews-pilot-v1',source:'PubMed',sampling:kind==='pair'?ve('pairMode').value:'catalog_order'}}
function persistEvent(e){try{if(ve('validationStorage').dataset.blocked)throw Error('Armazenamento local indisponível. Recupere um backup ou use outro navegador.');audit=V.save(localStorage,audit,e);validationStats();feedback('Decisão salva neste navegador. Exporte o backup ao terminar a sessão.');return true}catch(e){feedback('Não foi salvo: '+e.message);return false}}
function saveRecord(){if(!requireReviewer()||!activeRecord)return;let raw=ve('studyCount').value.trim();let e={...baseEvent('record',[activeRecord]),decision:ve('eligibility').value,reason:ve('exclusionReason').value.trim(),objective:ve('correctObjective').value.trim(),objective_status:ve('objectiveStatus').value,count:raw===''?null:Number(raw),unit:ve('countUnit').value,count_status:ve('countStatus').value,evidence:ve('countEvidence').value.trim(),notes:ve('recordNotes').value.trim()};if(persistEvent(e))nextRecord()}
function buildPairs(){let seen=new Set();pairCandidates=[];let mode=ve('pairMode').value;for(let i=0;i<data.length;i++){let ids=mode==='neighbors'?[data[i].id,data[i].similar[0]?.id]:[data[i].id,data[(i*7919+104729)%data.length].id];if(!ids[1]||ids[0]===ids[1])continue;ids.sort();let k=ids.join('|');if(!seen.has(k)){seen.add(k);pairCandidates.push(ids)}}queueOffset=0}
function openPair(ids){if(ids.length!==2||ids[0]===ids[1]||ids.some(id=>!data.some(d=>d.id===id))){feedback('Informe dois PMIDs diferentes presentes na base.');return}activePair=ids.slice().sort();let ds=activePair.map(id=>data.find(d=>d.id===id));ve('pairSources').innerHTML=ds.map(d=>`<div class="panel">${recordSource(d)}<div class="field"><small>Objetivo extraído automaticamente; conferir no resumo</small>${esc(d.objective||'Não extraído')}</div></div>`).join('');let old=V.latest(audit,reviewer(),'pair',meta.run).find(e=>e.ids.slice().sort().join('|')===activePair.join('|'));ve('pairDecision').value=old?.decision||'';ve('pairNotes').value=old?.notes||'';ve('pairPMIDA').value=activePair[0];ve('pairPMIDB').value=activePair[1];validationStats()}
function nextPair(){if(ve('pairMode').value==='manual'){feedback('Seleção manual: informe dois PMIDs e clique em Abrir par.');return}if(!pairCandidates.length)buildPairs();let done=new Set(V.latest(audit,reviewer(),'pair',meta.run).map(e=>e.ids.slice().sort().join('|')));while(queueOffset<pairCandidates.length){let p=pairCandidates[queueOffset++];if(!done.has(p.join('|'))){openPair(p);return}}feedback('Fila de pares concluída para este avaliador. Troque a origem ou informe dois PMIDs.')}
function savePair(){if(!requireReviewer()||activePair.length!==2)return;let e={...baseEvent('pair',activePair),decision:ve('pairDecision').value,notes:ve('pairNotes').value.trim()};if(persistEvent(e))nextPair()}
function downloadValidation(content,name,type){let u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function exportValidationJSON(){downloadValidation(JSON.stringify({schema:'orthoevidence.annotations.v1',exported_at:new Date().toISOString(),events:audit},null,2),'ortho-avaliacoes-backup.json','application/json')}
function exportValidationCSV(){let keys=['event_id','kind','reviewer','run','saved_at','protocol','sampling','ids','hashes','decision','reason','objective_status','objective','count_status','count','unit','evidence','notes'];let rows=[keys,...audit.map(e=>keys.map(k=>Array.isArray(e[k])?e[k].join('|'):e[k]??''))];const cell=v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';downloadValidation('\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'ortho-avaliacoes-historico.csv','text/csv;charset=utf-8')}
async function importValidation(file){if(!file)return;try{if(file.size>10000000)throw Error('Backup excede 10 MB.');let p=JSON.parse(await file.text());if(p.schema!=='orthoevidence.annotations.v1'||!Array.isArray(p.events))throw Error('Formato de backup incompatível.');let next=V.merge(audit,p.events);localStorage.setItem('orthoevidence.annotations.v1',JSON.stringify(next));audit=next;delete ve('validationStorage').dataset.blocked;ve('validationStorage').textContent='Avaliações salvas somente neste navegador. Faça backup ao terminar a sessão. Código de avaliador é autodeclarado, sem autenticação.';validationStats();feedback('Backup incorporado; decisões anteriores foram preservadas.');}catch(e){feedback('Importação cancelada: '+e.message)}ve('validationImport').value=''}
ve('reviewerCode').addEventListener('change',()=>{activeRecord='';activePair=[];queueOffset=0;renderValidation()});
ve('pairMode').addEventListener('change',()=>{buildPairs();nextPair()});

function quickDecision(decision){
 if(!requireReviewer()||!activeRecord)return;
 let reason=ve('exclusionReason').value.trim();
 if(decision==='exclude'&&(!reason||reason==='Outro motivo — especificar abaixo')){ve('eligibility').value='exclude';feedback('Informe o motivo e clique novamente em Excluir e avançar.');ve('exclusionReason').focus();return}
 let previous=V.latest(audit,reviewer(),'record',meta.run).find(e=>e.ids[0]===activeRecord);
 let e={...baseEvent('record',[activeRecord]),decision,reason,objective:previous?.objective||'',objective_status:previous?.objective_status||'not_checked',count:previous?.count??null,unit:previous?.unit||'studies',count_status:previous?.count_status||'not_checked',evidence:previous?.evidence||'',notes:previous?.notes||'',stage:'eligibility_only'};
 if(persistEvent(e))nextRecord();
}
